import{_ as e,o as t,f as r,a6 as o}from"./chunks/framework.BFhbG0o2.js";const m=JSON.parse('{"title":"从提示词到交付：AIGC 工作流如何沉淀","description":"把需求、变量、生成、人工判断和复盘连成可复用的生产系统。","frontmatter":{"title":"从提示词到交付：AIGC 工作流如何沉淀","description":"把需求、变量、生成、人工判断和复盘连成可复用的生产系统。","pageClass":"page-article-detail","status":"published"},"headers":[],"relativePath":"blog/aigc-workflow-system.md","filePath":"blog/aigc-workflow-system.md"}'),l={name:"blog/aigc-workflow-system.md"};function i(s,a,h,c,n,p){return t(),r("div",null,[...a[0]||(a[0]=[o('<h1 id="从提示词到交付-aigc-工作流如何沉淀" tabindex="-1">从提示词到交付：AIGC 工作流如何沉淀 <a class="header-anchor" href="#从提示词到交付-aigc-工作流如何沉淀" aria-label="Permalink to &quot;从提示词到交付：AIGC 工作流如何沉淀&quot;">​</a></h1><p>很多 AI 项目停留在“找到一个有效 Prompt”。但 Prompt 只能描述一次生成条件，真正可复用的工作流还要包含需求、参考、变量、筛选、精修、交付和复盘。</p><h2 id="从目标而不是工具开始" tabindex="-1">从目标而不是工具开始 <a class="header-anchor" href="#从目标而不是工具开始" aria-label="Permalink to &quot;从目标而不是工具开始&quot;">​</a></h2><p>同一个模型可以生成大量风格，但商业项目关心的是目标受众、使用场景和交付限制。先明确验收标准，才能知道哪些方向值得探索。</p><h2 id="保存变量关系" tabindex="-1">保存变量关系 <a class="header-anchor" href="#保存变量关系" aria-label="Permalink to &quot;保存变量关系&quot;">​</a></h2><p>只保存最终 Prompt，很难解释结果为什么有效。更有价值的记录包括参考图、模型版本、构图变化、失败方向和筛选理由。这样才能区分偶然结果与可重复方法。</p><h2 id="把人工判断写出来" tabindex="-1">把人工判断写出来 <a class="header-anchor" href="#把人工判断写出来" aria-label="Permalink to &quot;把人工判断写出来&quot;">​</a></h2><p>AI 可以扩展方向，但不能代替设计师确认产品事实、品牌一致性和商业风险。将这些判断整理为检查项，团队协作时才不会只依赖个人感觉。</p><h2 id="交付之后才开始沉淀" tabindex="-1">交付之后才开始沉淀 <a class="header-anchor" href="#交付之后才开始沉淀" aria-label="Permalink to &quot;交付之后才开始沉淀&quot;">​</a></h2><p>项目结束后，把有效结构、模板、命名规则和复盘结论放回资源库。下一次同类任务直接从已有资产开始，工作流才真正产生复利。</p><h2 id="关联内容" tabindex="-1">关联内容 <a class="header-anchor" href="#关联内容" aria-label="Permalink to &quot;关联内容&quot;">​</a></h2><ul><li><a href="/aigc/commercial-visual-system.html">AI 商业视觉生产系统</a></li><li><a href="/resources/mj-prompt.html">商业视觉 Prompt 结构</a></li><li><a href="/resources/notion.html">AI 项目复盘清单</a></li></ul><p><a href="/blog/">← 返回方法与洞察</a></p>',13)])])}const u=e(l,[["render",i]]);export{m as __pageData,u as default};
